// node Design/bake.mjs -> Sources/BikeShapes.swift (baked from Design/bikes.js; do not edit the Swift by hand)
import { readFileSync, writeFileSync } from 'node:fs';
const dir = new URL('.', import.meta.url);
new Function(readFileSync(new URL('bikes.js', dir), 'utf8'))();
const D = globalThis.DESIGN;
const n = v => Number.isInteger(v) ? v.toFixed(1) : String(v);
const q = s => JSON.stringify(s);
const kinds = Object.entries(D.bikes).filter(([, l]) => l.length);
let out = `// Generated by Design/bake.mjs from Design/bikes.js. Edit the design there, then run: node Design/bake.mjs
import Foundation

struct ShapeLayer { let z:Int; let t:Character; let role:String; let d:String; let w:Double; let a:Double; let x:Double; let y:Double; let r:Double; let str:String }

enum BikeShapes {
    static func layers(_ kind:BikeKind)->[ShapeLayer] { table[kind] ?? [] }
    private static let table:[BikeKind:[ShapeLayer]] = [${kinds.length ? '' : ':'}
`;
for (const [kind, layers] of kinds) {
  out += `        .${kind}: [\n`;
  for (const l of layers) {
    const f = { z: l.z, t: `"${l.t}"`, role: q(l.role), d: q(l.d || ''), w: n(l.w ?? l.ol ?? 0), a: n(l.a ?? 1), x: n(l.x ?? 0), y: n(l.y ?? 0), r: n(l.r ?? l.size ?? 0), str: q(l.str || '') };
    out += `            ShapeLayer(z:${f.z},t:${f.t},role:${f.role},d:${f.d},w:${f.w},a:${f.a},x:${f.x},y:${f.y},r:${f.r},str:${f.str}),\n`;
  }
  out += `        ],\n`;
}
out += `    ]\n}\n`;
writeFileSync(new URL('../Sources/BikeShapes.swift', dir), out);
console.log('BikeShapes.swift written');
